def algorithm_x(matrix={{matrix}}):
    rows = {i: set(j for j, v in enumerate(row) if v) for i, row in enumerate(matrix)}
    cols = {j: set(i for i in rows if j in rows[i]) for j in range(len(matrix[0]))}
    solution = []
    def solve():
        if not cols: return True
        c = min(cols, key=lambda x: len(cols[x]))
        if not cols[c]: return False
        for r in list(cols[c]):
            solution.append(r)
            removed_cols = []
            for j in rows[r]:
                for i in cols[j]:
                    for k in rows[i]:
                        if k != j: cols[k].discard(i)
                removed_cols.append((j, cols.pop(j)))
            if solve(): return True
            for j, col in reversed(removed_cols):
                cols[j] = col
                for i in col:
                    for k in rows[i]:
                        if k != j: cols[k].add(i)
            solution.pop()
        return False
    return solution if solve() else None
